/**
 * @method
 * @name tx_fn_SearchEtcDetail
 * @description Search Etc Detail 서버 호출
 * @param {*} action 제출 주소(호출부가 as-is form.action 으로 정하던 분기별 URL · 생략 시 기본 주소)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_SearchEtcDetail = async function (action) {
    const sbmOptions = {
        id: "tx_fn_SearchEtcDetail",
        method: "post",
        action: action ?? "/support/education.do",
        ref: "dma_SearchEtcDetailReq",
        target: "dlt_educationList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_load_list
 * @description load list 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_load_list = async function () {
    const sbmOptions = {
        id: "tx_load_list",
        method: "post",
        action: "/support/education.do?method=searchEducation",
        ref: "dma_loadListReq",
        target: "dlt_educationList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    const rj = res && res.responseJSON;
    const tot = rj && (rj["total"] != null ? rj["total"] : (rj.body && rj.body["total"]));
    if (tot != null && tot !== "") {
        $c.util.getComponent("krxpage_pagenavigator_66").setCount(Math.ceil(Number(tot) / 10));
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name grd_educationList_fmt_chrgTpNm
 * @description grd education List fmt chrg Tp Nm 처리
 * @param {*} data 데이터
 * @param {*} formattedData 포맷된 값
 * @param {*} r r
 * @param {*} c c
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_educationList_fmt_chrgTpNm = async function (data, formattedData, r, c) {
    try {
        const dl = $c.util.getComponent("dlt_educationList");
        const v = String(dl && dl.getCellData ? (dl.getCellData(r, "chrgTpNm") ?? '') : '');
        if (v === '공시책임자') { return '<a href="javascript:void(0)"' + (true ? ' class="lnk"' : '') + '>' + (console.error('[sdd] 미실현 라벨 갈래: chrgTpNm (expression)'), String(data ?? '')) + '</a>'; }
        if (v === '공시담당자') { return '<a href="javascript:void(0)"' + (true ? ' class="lnk"' : '') + '>' + (console.error('[sdd] 미실현 라벨 갈래: chrgTpNm (expression)'), String(data ?? '')) + '</a>'; }
        return '<a href="javascript:void(0)"' + (true ? ' class="lnk"' : '') + '>' + (console.error('[sdd] 미실현 라벨 갈래: chrgTpNm (expression)'), String(data ?? '')) + '</a>';
    } catch (e) { await $c.exception.handleError(e, { notify: 'none', context: "grd_educationList.chrgTpNm" }); return String(data ?? ''); }
};

/**
 * @method
 * @name grd_educationList_fmt_column4
 * @description grd education List fmt column4 처리
 * @param {*} data 데이터
 * @param {*} formattedData 포맷된 값
 * @param {*} r r
 * @param {*} c c
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_educationList_fmt_column4 = async function (data, formattedData, r, c) {
    try {
        const dl = $c.util.getComponent("dlt_educationList");
        const v = String(dl && dl.getCellData ? (dl.getCellData(r, "submitYn") ?? '') : '');
        if (v === 'Y') { return "신청완료"; }
        return "미제출";
    } catch (e) { await $c.exception.handleError(e, { notify: 'none', context: "grd_educationList.column4" }); return String(data ?? ''); }
};

/**
 * @method
 * @name search
 * @description search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function () {
    $c.util.getComponent('dma_SearchReq').set('method', 'searchSubmitEducationList');
    await scwin.tx_fn_Search('education.do');
};

/**
 * @method
 * @name searchRspnDetail
 * @description search Rspn Detail 처리
 * @param {*} disclsEduApplSeq disclsEduApplSeq
 * @param {String} chrgTpCd chrgTpCd
 * @param {String} disclsBzChrgAssgnDd disclsBzChrgAssgnDd
 * @param {*} seq seq
 * @param {String} editAvailYn editAvailYn
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchRspnDetail = async function (disclsEduApplSeq, chrgTpCd, disclsBzChrgAssgnDd, seq, editAvailYn) {
    $c.util.getComponent('dma_SearchReq').set('method', 'findEducationResponsibilityDetail');
    $c.util.getComponent('dma_SearchReq').set('disclsEduApplSeq', disclsEduApplSeq);
    $c.util.getComponent('dma_SearchReq').set('chrgTpCd', chrgTpCd);
    $c.util.getComponent('dma_SearchReq').set('disclsBzChrgAssgnDd', disclsBzChrgAssgnDd);
    $c.util.getComponent('dma_SearchReq').set('seq', seq);
    $c.util.getComponent('dma_SearchReq').set('editAvailYn', editAvailYn);
    const nr = await scwin.tx_fn_SearchRspnDetail('eduRspn.do');
    if (nr && nr.responseJSON && nr.responseJSON.success === true) {
        $c.win.moveUrl("/jldfil16403/jldfil16403.xml", { "method": 'findEducationResponsibilityDetail', "disclsEduApplSeq": disclsEduApplSeq, "chrgTpCd": chrgTpCd, "disclsBzChrgAssgnDd": disclsBzChrgAssgnDd, "seq": seq, "editAvailYn": editAvailYn });
    }
};

/**
 * @method
 * @name searchChrgDetail
 * @description search Chrg Detail 처리
 * @param {*} disclsEduApplSeq disclsEduApplSeq
 * @param {*} seq seq
 * @param {String} editAvailYn editAvailYn
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchChrgDetail = async function (disclsEduApplSeq, seq, editAvailYn) {
    $c.util.getComponent('dma_SearchReq').set('method', 'findEducationChargeDetail');
    $c.util.getComponent('dma_SearchReq').set('disclsEduApplSeq', disclsEduApplSeq);
    $c.util.getComponent('dma_SearchReq').set('seq', seq);
    $c.util.getComponent('dma_SearchReq').set('editAvailYn', editAvailYn);
    const nr = await scwin.tx_fn_SearchChrgDetail('eduChrg.do');
    if (nr && nr.responseJSON && nr.responseJSON.success === true) {
        $c.win.moveUrl("/jldfil16404/jldfil16404.xml", { "method": 'findEducationChargeDetail', "disclsEduApplSeq": disclsEduApplSeq, "seq": seq, "editAvailYn": editAvailYn });
    }
};

/**
 * @method
 * @name searchEtcDetail
 * @description search Etc Detail 처리
 * @param {*} disclsEduApplSeq disclsEduApplSeq
 * @param {*} seq seq
 * @param {String} editAvailYn editAvailYn
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchEtcDetail = async function (disclsEduApplSeq, seq, editAvailYn) {
    $c.util.getComponent('dma_SearchReq').set('method', 'findEducationEtcDetail');
    $c.util.getComponent('dma_SearchReq').set('disclsEduApplSeq', disclsEduApplSeq);
    $c.util.getComponent('dma_SearchReq').set('seq', seq);
    $c.util.getComponent('dma_SearchReq').set('editAvailYn', editAvailYn);
    const nr = await scwin.tx_fn_SearchEtcDetail('education.do');
    if (nr && nr.responseJSON && nr.responseJSON.success === true) {
        $c.win.moveUrl("/jldfil16405/jldfil16405.xml", { "method": 'findEducationEtcDetail', "disclsEduApplSeq": disclsEduApplSeq, "seq": seq, "editAvailYn": editAvailYn });
    }
};
